export interface GlobalOptions {
	url?: string;
	keypair?: string;
	programId?: string;
	simulate?: boolean;
	json?: boolean;
	computeUnitLimit?: string;
}

/** The most compute units a transaction may request. */
export const MAX_COMPUTE_UNIT_LIMIT = 1_400_000;

/** Registers the shared global options on one commander command. */
export function registerGlobals(command: Command): Command {
	return command
		.option(
			"-u, --url <url>",
			"RPC endpoint: mainnet, devnet, testnet, localhost, or an https URL.",
		)
		.option("-k, --keypair <path>", "Payer keypair JSON file.")
		.option("--program-id <address>", "Override the on-chain program address.")
		.option(
			"--simulate",
			"Simulate the transaction and print logs instead of sending.",
		)
		.option("--json", "Print machine-readable JSON output.")
		.option(
			"--compute-unit-limit <units>",
			"Compute unit limit to request instead of the one recorded for the instruction.",
		);
}

export class CliError extends Error {}

export class CliContext {
	readonly rpc: ReturnType<typeof createSolanaRpc>;
	readonly payer: KeyPairSigner;
	readonly programAddress: Address;
	readonly simulate: boolean;
	readonly json: boolean;
	/** `--compute-unit-limit`, which replaces every instruction's recorded limit. */
	readonly computeUnitLimit: number | undefined;
	private readonly cluster: string;

	private constructor(
		rpc: ReturnType<typeof createSolanaRpc>,
		payer: KeyPairSigner,
		programAddress: Address,
		simulate: boolean,
		json: boolean,
		computeUnitLimit: number | undefined,
		cluster: string,
	) {
		this.rpc = rpc;
		this.payer = payer;
		this.programAddress = programAddress;
		this.simulate = simulate;
		this.json = json;
		this.computeUnitLimit = computeUnitLimit;
		this.cluster = cluster;
	}

	static async create(options: GlobalOptions): Promise<CliContext> {
		const url = options.url ?? process.env.SOLANA_URL ?? "devnet";
		const keypair = options.keypair ?? process.env.PINA_KEYPAIR ??
			"~/.config/solana/id.json";
		const endpoint = resolveEndpoint(url);
		const rpc = createSolanaRpc(
			endpoint as Parameters<typeof createSolanaRpc>[0],
		);
		const payer = await loadKeypair(keypair);
		const programAddress = options.programId
			? pubkey("--program-id", options.programId)
			: ("Fc5A5xvNQ6w7kn2P7FpC18JNpDutLCRa14Q6gttxyPjd" as Address);
		const computeUnitLimit = parseComputeUnitLimit(options.computeUnitLimit);
		return new CliContext(
			rpc,
			payer,
			programAddress,
			options.simulate ?? false,
			options.json ?? false,
			computeUnitLimit,
			clusterOf(endpoint),
		);
	}

	/**
	 * Send or simulate one instruction, printing the result.
	 *
	 * `recordedLimit` is the compute unit limit the IDL records for the
	 * instruction. `--compute-unit-limit` replaces it; with neither, the
	 * transaction requests no limit and the runtime default applies.
	 */
	async send(instruction: Instruction, recordedLimit?: number): Promise<void> {
		const computeUnitLimit = this.computeUnitLimit ?? recordedLimit;
		const { value: latestBlockhash } = await this.rpc
			.getLatestBlockhash()
			.send();
		const message = buildTransactionMessage(
			this.payer,
			latestBlockhash,
			instruction,
			computeUnitLimit,
		);

		if (this.simulate) {
			const transaction = await signTransactionMessageWithSigners(message);
			const base64 = getBase64EncodedWireTransaction(transaction);
			const simulation = await this.rpc
				.simulateTransaction(base64, {
					encoding: "base64",
					sigVerify: false,
					replaceRecentBlockhash: true,
				})
				.send();
			const result = simulation.value;
			const logs = result.logs ?? [];
			// The RPC reports consumption as a bigint, which JSON cannot encode;
			// it never exceeds the transaction limit, so a number is exact.
			const unitsConsumed = result.unitsConsumed === undefined
				? null
				: Number(result.unitsConsumed);
			if (this.json) {
				console.log(
					JSON.stringify({
						logs,
						unitsConsumed,
						computeUnitLimit: computeUnitLimit ?? null,
					}),
				);
			} else {
				for (const log of logs) {
					console.log(log);
				}
				if (unitsConsumed !== null) {
					console.log(consumptionSummary(unitsConsumed, computeUnitLimit));
				}
			}
			if (result.err != null) {
				throw new CliError(
					`the transaction failed: ${JSON.stringify(result.err)}\n${
						logs.join("\n")
					}`,
				);
			}
			return;
		}

		const signatureBytes = await signAndSendTransactionMessageWithSigners(
			message,
		);
		const signature58 = getBase58Decoder().decode(signatureBytes);
		if (this.json) {
			console.log(JSON.stringify({ signature: signature58 }));
		} else {
			console.log(`Signature: ${signature58}`);
			const suffix = this.cluster ? `?cluster=${this.cluster}` : "";
			console.log(`https://explorer.solana.com/tx/${signature58}${suffix}`);
		}
	}
}

/**
 * The transaction message a command sends: one `SetComputeUnitLimit` first
 * when a limit is requested, then the command's instruction.
 */
export function buildTransactionMessage(
	payer: KeyPairSigner,
	latestBlockhash: BlockhashLifetimeConstraint,
	instruction: Instruction,
	computeUnitLimit: number | undefined,
) {
	return pipe(
		createTransactionMessage({ version: 0 }),
		(m) => setTransactionMessageFeePayerSigner(payer, m),
		(m) => setTransactionMessageLifetimeUsingBlockhash(latestBlockhash, m),
		(m) => setTransactionMessageComputeUnitLimit(computeUnitLimit, m),
		(m) => appendTransactionMessageInstructions([instruction], m),
	);
}

/**
 * Parse `--compute-unit-limit`: a whole number of compute units from 1 to
 * the transaction maximum, or `undefined` when the flag is absent.
 */
export function parseComputeUnitLimit(
	value: string | undefined,
): number | undefined {
	if (value === undefined) {
		return undefined;
	}
	const units = Number(value);
	if (!/^[0-9]+$/.test(value) || units < 1 || units > MAX_COMPUTE_UNIT_LIMIT) {
		throw new CliError(
			`--compute-unit-limit must be a whole number from 1 to ${MAX_COMPUTE_UNIT_LIMIT}`,
		);
	}
	return units;
}

/** How much of the requested budget a simulation consumed. */
export function consumptionSummary(
	consumed: number,
	computeUnitLimit: number | undefined,
): string {
	return computeUnitLimit === undefined
		? `Consumed ${consumed} compute units (no limit requested; the runtime default applies)`
		: `Consumed ${consumed} of ${computeUnitLimit} requested compute units`;
}

export function pubkey(flag: string, value: string): Address {
	if (!isAddress(value)) {
		throw new CliError(`${flag} must be a base58 public key`);
	}
	return value;
}

export function smallInteger(flag: string, value: string): number {
	const parsed = Number(value);
	if (!Number.isSafeInteger(parsed)) {
		throw new CliError(`${flag} must be an integer`);
	}
	return parsed;
}

export function bigInteger(flag: string, value: string): bigint {
	try {
		return BigInt(value);
	} catch {
		throw new CliError(`${flag} must be a 64-bit integer`);
	}
}

export function base58Vec(flag: string, value: string): number[] {
	const fixed = base58(flag, value);
	return Array.from(fixed);
}

export function base58(flag: string, value: string): Uint8Array {
	try {
		const ALPHABET =
			"123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";
		let num = 0n;
		for (const character of value) {
			const digit = ALPHABET.indexOf(character);
			if (digit < 0) {
				throw new Error("invalid character");
			}
			num = num * 58n + BigInt(digit);
		}
		const bytes: number[] = [];
		while (num > 0n) {
			bytes.unshift(Number(num % 256n));
			num /= 256n;
		}
		let leading = 0;
		for (const character of value) {
			if (character !== "1") break;
			leading += 1;
		}
		return new Uint8Array([...new Array<number>(leading).fill(0), ...bytes]);
	} catch {
		throw new CliError(`${flag} must be valid base58`);
	}
}

function resolveEndpoint(value: string): string {
	const endpoint = CLUSTERS[value] ?? value;
	if (!endpointIsSecure(endpoint)) {
		throw new CliError(
			"plaintext http:// endpoints are only allowed on localhost; use https for remote clusters",
		);
	}
	return endpoint;
}

function clusterOf(endpoint: string): string {
	let host: string;
	try {
		host = new URL(endpoint).hostname;
	} catch {
		return "";
	}
	if (host === "api.mainnet-beta.solana.com") return "";
	if (host === "api.devnet.solana.com") return "devnet";
	if (host === "api.testnet.solana.com") return "testnet";
	return "";
}

async function loadKeypair(path: string): Promise<KeyPairSigner> {
	const expanded = path.startsWith("~/")
		? `${homedir()}/${path.slice(2)}`
		: path;
	const bytes = JSON.parse(readFileSync(expanded, "utf8")) as unknown;
	if (!Array.isArray(bytes) || bytes.length !== 64) {
		throw new CliError(
			`could not load payer keypair \`${expanded}\`: expected a JSON array of 64 bytes`,
		);
	}
	// A value outside 0-255 would be silently wrapped by `Uint8Array`,
	// producing a different signer than the file asked for.
	for (const byte of bytes) {
		if (
			!Number.isInteger(byte) || (byte as number) < 0 || (byte as number) > 255
		) {
			throw new CliError(
				`could not load payer keypair \`${expanded}\`: every byte must be an integer from 0 to 255`,
			);
		}
	}
	return await createKeyPairSignerFromBytes(new Uint8Array(bytes as number[]));
}
